        // forced rebuild of the SAME window re-counts the pages and the base from
        // the new grid; the page, the offset inside it and the pick's origin are
        // untouched, so the words stay where the reader put them.
        applyReadingRestage(true, /*forceRebuild=*/ true);
    }
```

