Implementation: build the same continuous text with per-item spans, then find the item containing the offset. Since item numbers are `chapterVerses` (skipping continuations) — a piece is {number, partIndex?}. The slide set is keyed by (number, part). For a whole paragraph, partIndex=0.

```qml
function pieceAtChapterOffset(charOffset) {
    if (!root.book || root.chapterVerses.length === 0)
        return null
    let at = 0
    for (const verse of root.chapterVerses) {
        const continuation = Number(verse.partIndex ?? 0) > 0
            || String(verse.number ?? "").indexOf("-") >= 0
        if (continuation)
            continue
        if (at > 0)
            at += 1                     // the joining space (see readingPagesFromChapter)
        const text = String(verse.text ?? "")
        if (charOffset <= at + text.length)
            return { number: Number(verse.number), partIndex: Number(verse.partIndex ?? 0) }
        at += text.length
    }
    const last = root.chapterVerses[root.chapterVerses.length - 1]
    return last ? { number: Number(last.number), partIndex: Number(last.partIndex ?? 0) } : null
}
```
