{"kind":"tool","id":"iJOAUq6NzQY","toolName":"write_file","input":{"path":"C:/Users/znwaj/AppData/Local/Temp/audit_signals.mjs","instructions":"One-off audit: find QML handlers that declare more parameters than their signal sends.","content":"import fs from "node:fs";
import path from "node:path";

const root = process.argv[2];
const files = [];
function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) { if (e.name !== "build" && !e.name.startsWith(".")) walk(p); }
    else if (e.name.endsWith(".qml")) files.push(p);
  }
}
walk(root);

// signal name -> { count, where }
const signals = new Map();
const sigRe = /^\s*signal\s+([A-Za-z_]\w*)\s*\(([^)]*)\)/gm;
for (const f of files) {
  const src = fs.readFileSync(f, "utf8");
  let m;
  while ((m = sigRe.exec(src)) !== null) {
    const name = m[1];
    const params = m[2].split(",").map(s => s.trim()).filter(Boolean);
    // Same name may be declared by several components; keep the largest arity seen.
    const prev = signals.get(name);
    if (!prev || params.length > prev.count)
      signals.set(name, { count: params.length, where: path.relative(root, f) });
  }
}

// handler `onName: (a, b) =>` or `onName: function (a, b)`
const findings = [];
const handlerRe = /\bon([A-Z]\w*)\s*:\s*(?:function\s*)?\(([^)]*)\)/g;
for (const f of files) {
  const src = fs.readFileSync(f, "utf8");
  let m;
  while ((m = handlerRe.exec(src)) !== null) {
    const name = m[1].charAt(0).toLowerCase() + m[1].slice(1);
    const params = m[2].split(",").map(s => s.trim()).filter(Boolean);
    const sig = signals.get(name);
    if (!sig) continue;                       // Qt built-in / C++ signal: not judged
    if (params.length > sig.count) {
      const line = src.slice(0, m.index).split("\n").length;
      findings.push({ file: path.relative(root, f), line, handler: "on" + m[1],
                      wants: params.join(", "), sends: sig.count,
                      declaredIn: sig.where });
    }
  }
}

findings.sort((a, b) => a.file.localeCompare(b.file) || a.line - b.line);
const byFile = new Map();
for (const f of findings) {
  if (!byFile.has(f.file)) byFile.set(f.file, []);
  byFile.get(f.file).push(f);
}
for (const [file, list] of byFile) {
  console.log(`\n${file}`);
  for (const f of list)
    console.log(`  :${f.line}  ${f.handler}(${f.wants}) but signal sends ${f.sends}  [declared in ${f.declaredIn}]`);
}
console.log(`\n${findings.length} finding(s) across ${byFile.size} file(s); ${signals.size} QML signal(s) known.`);
