bool LiveOutputService::jumpToGroup(const QString &tag)
{
    if (!live_ || tag.isEmpty())
        return false;
    auto r = pl::PresentationEngine::Instance().JumpByTag(tag.toStdString());
    if (r.ok()) {
        refreshOnAirSlide();
        emit onAirChanged();
        return true;
    }
    return false;
}

