{"kind":"tool","id":"ibKT7AJ1tqI","toolName":"write_file","input":{"path":"qml/components/RoutingPort.qml","instructions":"Add the drag-to-connect port dot for the routing canvas.","content":"import QtQuick
import VGRPresenterUI

// A typed connection point on the Settings · Routing canvas.
//
// The canvas POSITIONS these (it owns the geometry formulas), so a port is a
// bare dot that knows which node it belongs to and reports its drag in SCENE
// coordinates — the canvas converts once with mapFromItem(null, …). Reporting
// the dot's own local x/y would fold its hit area's margin into every point,
// which is the bug PortDot.qml's header records from the Audio & Video board.
Rectangle {
    id: root

    // The canvas's key for the node this port belongs to.
    property string nodeKey: ""
    // The signal colour this port carries (audio / video / style).
    property color portColor: Theme.accent
    // Something is wired through this port — it stays lit instead of grey.
    property bool connected: false
    // This port is where the live drag started / where it would land.
    property bool dragOrigin: false
    property bool dragTarget: false

    signal dragStarted(real sceneX, real sceneY)
    signal dragMoved(real sceneX, real sceneY)
    signal dragEnded(real sceneX, real sceneY)

    width: 9
    height: 9
    radius: 4.5
    color: (root.connected || root.dragOrigin || root.dragTarget || handle.containsMouse)
           ? root.portColor : Theme.textMuted
    border.color: Theme.surface
    border.width: 1.5
    z: 3

    Behavior on color { ColorAnimation { duration: 100 } }

    MouseArea {
        id: handle
        // The dot is 9px; the handle is 25px. A 9px grab target made the connect
        // gesture fiddly (the Audio & Video board's port was widened to 28px for
        // exactly this), and cards sit 74px apart so a neighbour can never be
        // stolen.
        anchors.fill: parent
        anchors.margins: -8
        cursorShape: Qt.CrossCursor
        // The gesture belongs to the port, not to the canvas's Flickable: without
        // this the page scrolls away mid-connect.
        preventStealing: true

        function sceneX(mx) { return handle.mapToItem(null, mx, 0).x }
        function sceneY(my) { return handle.mapToItem(null, 0, my).y }

        onPressed: (mouse) => root.dragStarted(handle.sceneX(mouse.x), handle.sceneY(mouse.y))
        onPositionChanged: (mouse) => root.dragMoved(handle.sceneX(mouse.x), handle.sceneY(mouse.y))
        onReleased: (mouse) => root.dragEnded(handle.sceneX(mouse.x), handle.sceneY(mouse.y))
    }
}
"}}


