function seed() {
    if (root.seeded) return
    if (root.busRows.length === 0 && root.screens.length === 0) return
    root.seeded = true
    const wires = []
    // 1. Styles: a screen that already carries a style on Settings · Outputs is
    //    wired to it. This one is REAL (OutputListModel.styleId).
    for (let s = 0; s < root.screens.length; ++s) {
        const styleId = root.screens[s].styleId
        if (!styleId) continue
        for (let t = 0; t < root.styles.length; ++t) {
            if (root.styles[t].id === styleId) { wires.push(root.edge("screen:" + s, "style:" + t, "style")); break }
        }
    }
    // 2. Video: the first bus that carries video feeds every screen ...
    let videoBus = -1
    for (let b = 0; b < root.busRows.length; ++b)
        if (root.busRows[b].type !== "audio") { videoBus = b; break }
    if (videoBus >= 0)
        for (let s = 0; s < root.screens.length; ++s) wires.push(root.edge("bus:" + videoBus, "screen:" + s, "video"))
    // 3. Audio: the first bus that carries audio feeds Speakers ...
    let audioBus = -1
    for (let b = 0; b < root.busRows.length; ++b)
        if (root.busRows[b].type !== "video") { audioBus = b; break }
    if (audioBus >= 0) {
        wires.push(root.edge("bus:" + audioBus, "sink:speakers", "audio"))
        // ... and the app's own streaming/ICEcast endpoints, so the sink column
        // shows a typed wire rather than an empty column.
        wires.push(root.edge("bus:" + audioBus, "sink:icecast", "audio"))
    }
    // 4. Screens → the sink that matches their kind (an NDI screen into NDI, an
    //    HDMI screen into HDMI), so "what this screen is feeding" reads on the
    //    sink card.
    for (let s = 0; s < root.screens.length; ++s) {
        const kind = String(root.screens[s].kind || "").toLowerCase()
        for (let t = 0; t < root.sinks.length; ++t) {
            const sink = root.sinks[t]
            if (kind && kind === sink.id && sink.accepts.indexOf("video") >= 0)
                wires.push(root.edge("screen:" + s, "sink:" + sink.id, "video"))
        }
    }
    root.edges = wires
}
