function toggleWire(a, b) {
    const kinds = root.wireKinds(a, b)
    if (kinds.length === 0) return false
    const from = root.nodeColumn(a) < root.nodeColumn(b) ? a : b
    const to   = root.nodeColumn(a) < root.nodeColumn(b) ? b : a
    let all = true
    for (let i = 0; i < kinds.length; ++i) if (!root.hasEdge(from, to, kinds[i])) all = false
    const next = root.edges.slice()
    if (all) {
        root.edges = next.filter((e) => !(e.from === from && e.to === to))
    } else {
