// Settings · Routing — the routing canvas: Buses | Screens | Styles | Outputs.
//
// THE DESIGN (docs: "Routing design for Buses, Screens, Styles and Outputs"):
// a node canvas in the Audio & Video screen's visual language, where a signal
// goes only where a wire puts it. Four layers, one column each:
//
//   Buses    carry audio and/or video, fed by the sources wired on Audio & Video
//   Screens  take video from a bus and have a list of styles
//   Styles   a look; one style can sit on many screens, one screen holds several
//   Outputs  the sinks (speakers, NDI, SDI, HDMI, HTML, Icecast, recording,
//            streaming) — each accepts only the signal types it can carry
//
// Wires are TYPED, which is the whole point: purple carries audio, orange video,
// blue dashed is a screen's style. A bus that carries both is wired as two
// parts, so the audio half can go to a sink that only takes audio while the
// video half goes to a screen. Dragging from a port to a card connects; dragging
// the same pair again takes the wire back out; right-click removes a wire.
// While a drag is live, every card that cannot take it steps back — the design's
// "not wired, not sent" rule made visible instead of refusing silently.
//
// WHAT IS WIRED TO WHAT IS NOT PERSISTED YET, AND NOTHING IS SENT. The rosters
// are the app's own (BusListModel, OutputListModel — which IS the screen roster,
// Settings · Outputs edits the same rows — and StyleListModel). The sink column
// is the design's fixed list: the engine has no sink entity until Phase 2, so
// these are declared here. The wire list lives in this screen and is seeded from
// the rosters on entry (see seed()); when the engine's screen/edge model lands,
// edges become a model read/write and the seeding block goes away.
Item {
    id: root

    // ---- Rosters, with the revision bridge every settings screen uses: the
    // models' Q_INVOKABLE reads are not tracked by QML's binding system, so
    // this counter is the honest dependency, bumped by the models' own signals.
    property int modelsRev: 0
    Connections {
        target: BusListModel
        function onDataChanged() { root.rostersChanged() }
        function onRowsInserted() { root.rostersChanged() }
        function onRowsRemoved() { root.rostersChanged() }
        function onModelReset() { root.rostersChanged() }
    }
    Connections {
        target: OutputListModel
        function onDataChanged() { root.rostersChanged() }
        function onRowsInserted() { root.rostersChanged() }
        function onRowsRemoved() { root.rostersChanged() }
        function onModelReset() { root.rostersChanged() }
        function onOutputRosterChanged() { root.rostersChanged() }
    }
    Connections {
        target: StyleListModel
        function onDataChanged() { root.rostersChanged() }
        function onRowsInserted() { root.rostersChanged() }
        function onRowsRemoved() { root.rostersChanged() }
        function onModelReset() { root.rostersChanged() }
        function onRosterChanged() { root.rostersChanged() }
    }

    readonly property var busRows: {
        root.modelsRev
        const out = []
        const n = BusListModel.rowCount()
        for (let i = 0; i < n; ++i) out.push(BusListModel.getBus(i))
        return out
    }
    readonly property var screenRows: {
        root.modelsRev
        const out = []
        const n = OutputListModel.rowCount()
        for (let i = 0; i < n; ++i) out.push(OutputListModel.getOutput(i))
        return out
    }
    readonly property var styleRows: {
        root.modelsRev
        const out = []
        const n = StyleListModel.rowCount()
        for (let i = 0; i < n; ++i) out.push(StyleListModel.getStyle(i))
        return out
    }
    // The design's §5 table, as rows — what each sink accepts is the rule the
    // canvas wires against, so it is declared beside the sink and nowhere else.
    readonly property var sinkRows: [
        { id: "speakers",  name: "Speakers",  icon: "volume2",      accepts: ["audio"] },
        { id: "icecast",   name: "Icecast",   icon: "cloudSync",    accepts: ["audio"] },
        { id: "ndi",       name: "NDI",       icon: "link",         accepts: ["audio", "video"] },
        { id: "sdi",       name: "SDI",       icon: "slide",        accepts: ["audio", "video"] },
        { id: "hdmi",      name: "HDMI",      icon: "presentation", accepts: ["video"] },
        { id: "html",      name: "HTML",      icon: "fileText",     accepts: ["video"] },
        { id: "recording", name: "Recording", icon: "activity",     accepts: ["audio", "video"] },
        { id: "streaming", name: "Streaming", icon: "zap",          accepts: ["audio", "video"] }
    ]

    // ---- The wires. { from, to, kind } — node keys are spelled once, in
    // nodeKeyOf, and only ever compared as whole strings.
    property var edges: []
    // Seeding runs once per screen instance, after the rosters have actually
    // loaded (they arrive after the deferred engine boot).
    property bool seeded: false

    // ---- Canvas geometry. ONE set of formulas for both the cards and the port
    // points: this screen draws the ports (the cards do not), so a wire's
    // endpoint and the dot it leaves from are computed from the same numbers and
    // can never disagree.
    readonly property int colHeaderH: 40
    readonly property int cardH: 64
    readonly property int rowGap: 10
    readonly property int gutter: 44
    readonly property real minBoardW: 4 * 130 + 3 * gutter

    readonly property real boardW: Math.max(flick.width, root.minBoardW)
    readonly property real colW: (root.boardW - root.gutter * 3) / 4
    readonly property int longestColumn: {
        root.modelsRev
        return Math.max(Math.max(root.busRows.length, root.screenRows.length),
                        Math.max(root.styleRows.length, root.sinkRows.length), 1)
    }
    readonly property real boardH: root.colHeaderH + root.longestColumn * (root.cardH + root.rowGap) + 10

    function columnX(column) { return column * (root.colW + root.gutter) }
    function rowTop(row) { return root.colHeaderH + row * (root.cardH + root.rowGap) }
    function portY(row) { return root.rowTop(row) + root.cardH / 2 }

    // ---- Node keys -----------------------------------------------------------
    function allKeys() {
        const keys = []
        for (let i = 0; i < root.busRows.length; ++i) keys.push("bus:" + i)
        for (let i = 0; i < root.screenRows.length; ++i) keys.push("screen:" + i)
        for (let i = 0; i < root.styleRows.length; ++i) keys.push("style:" + i)
        for (let i = 0; i < root.sinkRows.length; ++i) keys.push("sink:" + root.sinkRows[i].id)
        return keys
    }
    // The column a key lives in — the column ORDER is the signal path, so this
    // is also how a backwards drag is normalised.
    function columnOf(key) {
        if (key.indexOf("bus:") === 0) return 0
        if (key.indexOf("screen:") === 0) return 1
        if (key.indexOf("style:") === 0) return 2
        if (key.indexOf("sink:") === 0) return 3
        return -1
    }
    function rowOf(key) {
        const at = key.indexOf(":")
        if (at < 0) return -1
        const rest = key.substring(at + 1)
        if (key.indexOf("sink:") === 0) {
            for (let i = 0; i < root.sinkRows.length; ++i)
                if (root.sinkRows[i].id === rest) return i
            return -1
        }
        const n = parseInt(rest, 10)
        return isNaN(n) ? -1 : n
    }
    function hasOut(key) { const c = root.columnOf(key); return c === 0 || c === 1 }
    function hasIn(key) { const c = root.columnOf(key); return c >= 1 }

    function portOut(key) {
        if (!root.hasOut(key)) return null
        const c = root.columnOf(key)
        const r = root.rowOf(key)
        if (c < 0 || r < 0) return null
        return { x: root.columnX(c) + root.colW, y: root.portY(r) }
    }
    function portIn(key) {
        if (!root.hasIn(key)) return null
        const c = root.columnOf(key)
        const r = root.rowOf(key)
        if (c < 0 || r < 0) return null
        return { x: root.columnX(c), y: root.portY(r) }
    }

    function busType(index) {
        const bus = root.busRows[index]
        return bus ? String(bus.type || "audio") : "audio"
    }
    function busHasAudio(index) { return root.busType(index) !== "video" }
    function busHasVideo(index) { return root.busType(index) !== "audio" }

    function sinkAccepts(index, kind) {
        const sink = root.sinkRows[index]
        return sink ? sink.accepts.indexOf(kind) >= 0 : false
    }

    // What a wire between these two nodes would carry — [] = the pair cannot be
    // wired at all. Both drag directions land here; the pair is normalised
    // left-to-right first because the column order IS the signal path.
    function wireKinds(a, b) {
        const ca = root.columnOf(a)
        const cb = root.columnOf(b)
        if (ca < 0 || cb < 0 || ca === cb) return []
        const fromCol = Math.min(ca, cb)
        const toCol = Math.max(ca, cb)
        const fromRow = root.rowOf(ca < cb ? a : b)
        const toRow = root.rowOf(ca < cb ? b : a)
        if (fromRow < 0 || toRow < 0) return []

        // bus → screen: video only (a screen renders pictures, not sound)
        if (fromCol === 0 && toCol === 1)
            return root.busHasVideo(fromRow) ? ["video"] : []
        // bus → sink: whatever BOTH sides carry (a both-bus into NDI = two wires)
        if (fromCol === 0 && toCol === 3) {
            const kinds = []
            if (root.busHasAudio(fromRow) && root.sinkAccepts(toRow, "audio")) kinds.push("audio")
            if (root.busHasVideo(fromRow) && root.sinkAccepts(toRow, "video")) kinds.push("video")
            return kinds
        }
        // screen → style: a look attached to a screen
        if (fromCol === 1 && toCol === 2) return ["style"]
        // screen → sink: video only
        if (fromCol === 1 && toCol === 3)
            return root.sinkAccepts(toRow, "video") ? ["video"] : []
        return []
    }

    function edgeIndex(from, to, kind) {
        for (let i = 0; i < root.edges.length; ++i) {
            const e = root.edges[i]
            if (e.from === from && e.to === to && e.kind === kind) return i
        }
        return -1
    }
    function hasEdge(from, to, kind) { return root.edgeIndex(from, to, kind) >= 0 }

    function edgesInto(key) {
        const out = []
        for (let i = 0; i < root.edges.length; ++i)
            if (root.edges[i].to === key) out.push(root.edges[i])
        return out
    }
    function edgesFrom(key) {
        const out = []
        for (let i = 0; i < root.edges.length; ++i)
            if (root.edges[i].from === key) out.push(root.edges[i])
        return out
    }
    function portConnected(key, side) {
        return side === "out" ? root.edgesFrom(key).length > 0 : root.edgesInto(key).length > 0
    }

    function wireColor(kind) {
        if (kind === "audio") return Theme.wireAudio
        if (kind === "style") return Theme.wireStyle
        return Theme.wireVideo
    }
    function portColorFor(key) {
        const c = root.columnOf(key)
        const r = root.rowOf(key)
        if (c === 0) {
            if (!root.busHasAudio(r)) return Theme.wireVideo
            if (!root.busHasVideo(r)) return Theme.wireAudio
            return Theme.accent
        }
        if (c === 1) return Theme.wireVideo
        if (c === 2) return Theme.wireStyle
        if (c === 3) {
            if (root.sinkAccepts(r, "audio") && root.sinkAccepts(r, "video")) return Theme.accent
            return root.sinkAccepts(r, "audio") ? Theme.wireAudio : Theme.wireVideo
        }
        return Theme.accent
    }

    // ---- Wires, resolved to points. A stale key (a bus deleted under a wire)
    // resolves to null and simply draws nothing — the design's "not wired, not
    // sent" state, never a line into empty space.
    readonly property var wires: {
        root.modelsRev
        const out = []
        for (let i = 0; i < root.edges.length; ++i) {
            const e = root.edges[i]
            const a = root.portOut(e.from)
            const b = root.portIn(e.to)
            if (a === null || b === null) continue
            out.push({ index: i, from: e.from, to: e.to, kind: e.kind, x1: a.x, y1: a.y, x2: b.x, y2: b.y })
        }
        return out
    }

    // ---- Hover / drag state --------------------------------------------------
    property int hoveredWire: -1
    property string hoveredNode: ""
    property bool dragging: false
    property string dragFrom: ""
    property real dragStartX: 0
    property real dragStartY: 0
    property real dragX: 0
    property real dragY: 0
    property string dropKey: ""
    // True while the pointer is over a point a wire could actually land on.
    readonly property bool dropOk: root.dragging && root.dropKey.length > 0
    readonly property string activeHoverKey: root.dragging ? root.dragFrom : root.hoveredNode

    function rostersChanged() {
        root.modelsRev++
        root.prune()
        root.seedIfReady()
    }

    // Drop wires whose endpoints no longer exist (a bus removed, a screen
    // deleted). Runs on every roster change, so a saved key can never outlive
    // the row it names.
    function prune() {
        const keys = root.allKeys()
        const kept = []
        for (let i = 0; i < root.edges.length; ++i) {
            const e = root.edges[i]
            if (keys.indexOf(e.from) >= 0 && keys.indexOf(e.to) >= 0) kept.push(e)
        }
        if (kept.length !== root.edges.length) root.edges = kept
    }

    // ---- Seeding -------------------------------------------------------------
    // Stands in for the design's first-run migration ("existing outputs keep
    // their current behaviour"): the rosters already say which bus feeds what and
    // which style a screen carries, so the canvas opens showing that picture
    // instead of an empty sheet. Everything here is UI-side until the engine's
    // model lands — in particular the AUDIO wires, which describe the intended
    // path: the app has no audio engine yet, so nothing is actually sent.
    function seedIfReady() {
        if (root.seeded) return
        if (root.busRows.length === 0 && root.screenRows.length === 0) return  // rosters not loaded yet
        root.seeded = true

        const wires = []
        const add = function (from, to, kind) {
            for (let i = 0; i < wires.length; ++i)
                if (wires[i].from === from && wires[i].to === to && wires[i].kind === kind) return
            wires.push({ from: from, to: to, kind: kind })
        }

        // 1. A screen wired to the style Settings · Outputs already gives it.
        for (let s = 0; s < root.screenRows.length; ++s) {
            const styleId = root.screenRows[s].styleId
            if (!styleId) continue
            for (let t = 0; t < root.styleRows.length; ++t) {
                if (root.styleRows[t].id === styleId) { add("screen:" + s, "style:" + t, "style"); break }
            }
        }

        // 2. The first bus that carries video feeds every screen — what the
        //    outputs render today (the on-air slide), drawn as the design wants
        //    it drawn: one bus, one wire per screen.
        let videoBus = -1
        let audioBus = -1
        for (let b = 0; b < root.busRows.length; ++b) {
            if (videoBus < 0 && root.busHasVideo(b)) videoBus = b
            if (audioBus < 0 && root.busHasAudio(b)) audioBus = b
        }
        if (videoBus >= 0) {
            for (let s = 0; s < root.screenRows.length; ++s)
                add("bus:" + videoBus, "screen:" + s, "video")
        }

        // 3. That bus's audio half to the audio sinks.
        if (audioBus >= 0) {
            add("bus:" + audioBus, "sink:speakers", "audio")
            add("bus:" + audioBus, "sink:icecast", "audio")
            add("bus:" + audioBus, "sink:recording", "audio")
        }

        // 4. A screen feeds the sink its own kind names (an NDI screen into NDI,
        //    an HDMI screen into HDMI), so the sink shows what it receives.
        for (let s = 0; s < root.screenRows.length; ++s) {
            const kind = String(root.screenRows[s].kind || "").toLowerCase()
            for (let t = 0; t < root.sinkRows.length; ++t) {
                if (kind.length > 0 && kind === root.sinkRows[t].id && root.sinkAccepts(t, "video"))
                    add("screen:" + s, "sink:" + root.sinkRows[t].id, "video")
            }
        }

        root.edges = wires
    }

    function resetWires() {
        root.edges = []
        root.seeded = false
        root.seedIfReady()
    }

    Component.onCompleted: root.seedIfReady()

    // ---- Connect gestures ----------------------------------------------------
    function canvasPoint(sceneX, sceneY) {
        const p = board.mapFromItem(null, sceneX, sceneY)
        return { x: p.x, y: p.y }
    }

    function beginDrag(key, sceneX, sceneY) {
        const p = root.canvasPoint(sceneX, sceneY)
        root.dragging = true
        root.dragFrom = key
        root.dragStartX = p.x
        root.dragStartY = p.y
        root.dragX = p.x
        root.dragY = p.y
        root.dropKey = ""
        root.hoveredWire = -1
    }

    function moveDrag(key, sceneX, sceneY) {
        if (!root.dragging || key !== root.dragFrom) return
        const p = root.canvasPoint(sceneX, sceneY)
        root.dragX = p.x
        root.dragY = p.y
        const over = root.nodeAt(p.x, p.y)
        root.dropKey = over === root.dragFrom ? "" : over
    }

    function endDrag(key, sceneX, sceneY) {
        if (!root.dragging || key !== root.dragFrom) return
        const p = root.canvasPoint(sceneX, sceneY)
        const over = root.nodeAt(p.x, p.y)
        root.dragging = false
        root.dragFrom = ""
        root.dropKey = ""
        if (over.length > 0 && over !== key) root.toggleWire(key, over)
    }

    // Which node's card contains this canvas point (the cards' rects are known
    // from the same formulas that place them).
    function nodeAt(x, y) {
        const keys = root.allKeys()
        for (let i = 0; i < keys.length; ++i) {
            const key = keys[i]
            const c = root.columnOf(key)
            const r = root.rowOf(key)
            if (c < 0 || r < 0) continue
            const left = root.columnX(c)
            const top = root.rowTop(r)
            if (x >= left - 13 && x <= left + root.colW + 13 &&
                y >= top - 8 && y <= top + root.cardH + 8)
                return key
        }
        return ""
    }

    // Second drag between the same pair takes the wire back out — the design's
    // "not wired, not sent" from the other direction.
    function toggleWire(a, b) {
        const kinds = root.wireKinds(a, b)
        if (kinds.length === 0) return false
        const from = root.columnOf(a) < root.columnOf(b) ? a : b
        const to = root.columnOf(a) < root.columnOf(b) ? b : a

        let all = true
        for (let i = 0; i < kinds.length; ++i)
            if (!root.hasEdge(from, to, kinds[i])) all = false

        const next = []
        for (let i = 0; i < root.edges.length; ++i) {
            const e = root.edges[i]
            if (all && e.from === from && e.to === to) continue      // remove the pair
            next.push(e)
        }
        if (!all) {
            for (let i = 0; i < kinds.length; ++i)
                if (!root.hasEdge(from, to, kinds[i])) next.push({ from: from, to: to, kind: kinds[i] })
        }
        root.edges = next
        return true
    }

    // ---- Wire hit-testing: one layer for every wire (never a handler on a wire
    // delegate — the Audio & Video board's header records the crash that pattern
    // caused when a rebuild destroyed the delegate under the cursor).
    function cubicAt(a, b, c, d, t) {
        const u = 1 - t
        return u * u * u * a + 3 * u * u * t * b + 3 * u * t * t * c + t * t * t * d
    }
    function wireAt(x, y) {
        const list = root.wires
        for (let i = 0; i < list.length; ++i) {
            const w = list[i]
            const dx = Math.max(24, Math.abs(w.x2 - w.x1) * 0.5)
            for (let s = 0; s <= 24; ++s) {
                const t = s / 24
                const px = root.cubicAt(w.x1, w.x1 + dx, w.x2 - dx, w.x2, t)
                const py = root.cubicAt(w.y1, w.y1, w.y2, w.y2, t)
                if (Math.abs(px - x) <= 7 && Math.abs(py - y) <= 7) return i
            }
        }
        return -1
    }
    function removeWireAt(x, y) {
        const at = root.wireAt(x, y)
        if (at < 0) return
        const next = root.edges.slice()
        next.splice(at, 1)
        root.edges = next
        root.hoveredWire = -1
    }

    // ---- Labels --------------------------------------------------------------
    function typeLabel(kind) {
        if (kind === "audio") return "Audio"
        if (kind === "video") return "Video"
        return "Audio + Video"
    }
    function typeBadge(kind) {
        if (kind === "audio") return "A"
        if (kind === "video") return "V"
        return "A+V"
    }
    function acceptsLabel(sink) {
        if (sink.accepts.length === 2) return "Audio + Video"
        return sink.accepts[0] === "audio" ? "Audio" : "Video"
    }
    function receivedLabel(key) {
        const into = root.edgesInto(key)
        if (into.length === 0) return "silent"
        let audio = false
        let video = false
        for (let i = 0; i < into.length; ++i) {
            if (into[i].kind === "audio") audio = true
            if (into[i].kind === "video") video = true
        }
        if (audio && video) return "audio + video"
        return audio ? "audio" : "video"
    }
    function screenFed(index) {
        return root.portConnected("screen:" + index, "in")
    }
    function screenVideoFed(index) {
        const into = root.edgesInto("screen:" + index)
        for (let i = 0; i < into.length; ++i)
            if (into[i].kind === "video") return true
        return false
    }
    function styleScreenCount(index) {
        return root.edgesFrom("screen:" + index).length >= 0
            ? root.edgesInto("style:" + index).length
            : 0
    }

    // =====================================================================
    // Header
    // =====================================================================
    Item {
        id: pageHeader
        x: Theme.space6
        y: Theme.space6
        width: parent.width - Theme.space6 * 2
        height: 68

        Column {
            anchors.left: parent.left
            anchors.top: parent.top
            width: Math.max(120, parent.width - legend.width - resetButton.width - Theme.space5 * 2)
            spacing: 3

            Text {
                text: qsTr("Routing")
                color: Theme.textPrimary
                font.family: Theme.fontFamily
                font.pixelSize: Theme.textXl
                font.weight: Font.DemiBold
            }
            Text {
                width: parent.width
                text: qsTr("Drag from a port to wire a signal — drag the same pair again to disconnect, or right-click a wire to remove it.")
                color: Theme.textSecondary
                font.family: Theme.fontFamily
                font.pixelSize: Theme.textSub
                wrapMode: Text.WordWrap
            }
            Text {
                width: parent.width
                // The honest state of this screen: it is the layout the engine's
                // routing model binds to, not a thing that sends yet.
                text: qsTr("Draft wiring — this graph is on screen only until the engine's routing model lands.")
                color: Theme.textMuted
                font.family: Theme.fontFamily
                font.pixelSize: Theme.textXs
                wrapMode: Text.WordWrap
            }
        }

        Row {
            id: legend
            anchors.right: resetButton.left
            anchors.rightMargin: Theme.space5
            anchors.verticalCenter: parent.verticalCenter
            spacing: Theme.space4

