{"kind":"tool","id":"ibXfsWN2BaI","toolName":"write_file","input":{"path":"qml/settings/RoutingDraft.qml","instructions":"Add the session-scoped routing wire store singleton.","content":"pragma Singleton
import QtQuick

// The wire state of Settings · Routing, for the whole app session.
//
// WHY A SINGLETON: the Settings card's Loader builds the selected screen fresh
// every time a section is picked, so a wire list owned by the screen would be
// wiped by a trip to Outputs and back — while the rosters it wires (buses,
// screens, styles) all survive. Holding the edges here makes the canvas read the
// same on the way back in, and it is the one object the engine's routing model
// replaces (or backs) when it lands: swap the storage in setEdges/edges and every
// reader on the canvas keeps working.
//
// Node keys — one spelling for every column:
//     "bus:<row>"   "screen:<row>"   "style:<row>"   "sink:<id>"
//
// Every edge is { from, to, kind } with kind "audio" | "video" | "style". The
// edges are TYPED because the design says so: a bus that carries both is two
// edges, so each half goes only where its output accepts it.
QtObject {
    id: root

    property var edges: []
    // True once the canvas has seeded the picture from the rosters, so leaving
    // and re-entering the section never re-adds what the user has removed.
    property bool seeded: false

    function setEdges(list) {
        root.edges = list === undefined || list === null ? [] : list
    }

    function indexOfEdge(from, to, kind) {
      [… 110 characters omitted] === from && e.to === to && e.kind === kind) return i
        }
        return -1
    }

    function hasEdge(from, to, kind) { return root.indexOfEdge(from, to, kind) >= 0 }

    function addEdge(from, to, kind) {
        if (root.indexOfEdge(from, to, kind) >= 0) return
        root.edges = root.edges.concat([{ from: from, to: to, kind: kind }])
    }

    function removeEdge(from, to, kind) {
        const at = root.indexOfEdge(from, to, kind)
        if (at < 0) return
        const next = root.edges.slice()
        next.splice(at, 1)
        root.edges = next
    }

    function removeAt(index) {
        if (index < 0 || index >= root.edges.length) return
        const next = root.edges.slice()
        next.splice(index, 1)
        root.edges = next
    }

    // Every wire touching a node — the hover highlight and the cards' own
    // "what is this node receiving" both read this.
    function edgesFor(nodeKey) {
        const out = []
        for (let i = 0; i < root.edges.length; ++i) {
            const e = root.edges[i]
            if (e.from === nodeKey || e.to === nodeKey) out.push(e)
        }
        return out
    }

    function countInto(nodeKey, kind) {
        let n = 0
        for (let i = 0; i < root.edges.length; ++i) {
            const e = root.edges[i]
            if (e.to === nodeKey && (kind === undefined || e.kind === kind)) n++
        }
        return n
    }

    function countFrom(nodeKey, kind) {
        let n = 0
        for (let i = 0; i < root.edges.length; ++i) {
            const e = root.edges[i]
            if (e.from === nodeKey && (kind === undefined || e.kind === kind)) n++
        }
        return n
    }

    // Drop every wire whose endpoints are not in `liveKeys` — a bus deleted, a
    // screen removed, a style renamed out of the roster. Called on every roster
    // change so a stale key can never draw a wire into nothing.
    function prune(liveKeys) {
        const kept = []
        for (let i = 0; i < root.edges.length; ++i) {
            const e = root.edges[i]
            if (liveKeys.indexOf(e.from) >= 0 && liveKeys.indexOf(e.to) >= 0) kept.push(e)
        }
        if (kept.length !== root.edges.length) root.edges = kept
    }

    function clear() {
        root.edges = []
        root.seeded = false
    }
}
