function portPoint(key, kind, side) {
    const c = root.columnOf(key)
    const r = root.rowOf(key)
    if (c < 0 || r < 0) return null
    const x = side === "out" ? root.columnX(c) + root.colW : root.columnX(c)
    return { x: x, y: root.portY(r) + root.portOffset(kind) }
}
