    // ---- The two style GATES (Overlays, Media) -----------------------------
    // The gates that used to be chips in Styles · Edit Style. They live at the
    // head of the STYLES column because they are allow-list facts an OUTPUT reads
    // — the same question the rest of this canvas answers with wires — and they
    // edit the ON-AIR style's own gate (the style the program is wearing), which
    // is the one an operator is actually gating.
    //
    // Media has no template and Overlays read their own design, so neither card
    // carries a template or a dot: they are gates, not layers.
    readonly property var gateCards: [
        { key: "overlay", title: qsTr("Overlays"),
          subtitle: qsTr("Overlay layer · on-air style") },
        { key: "media", title: qsTr("Media"),
          subtitle: qsTr("Media · on-air style") }
    ]
    // Bumped on every card click: StyleListModel::setShowTemplate emits
    // dataChanged, which is not a signal this page listens to, so the cards' own
    // read of the gate has to be told it changed.
    property int gateRev: 0
    readonly property int activeStyleRow: {
        root.modelsRev
        root.gateRev
        const id = String(OutputListModel.activeStyleId || "")
        return id.length > 0 ? StyleListModel.rowForId(id) : -1
    }
    readonly property var activeStyleGates: {
        root.modelsRev
        root.gateRev
        const row = root.activeStyleRow
        return row >= 0 ? StyleListModel.getStyle(row) : ({})
    }
    readonly property bool gatesEditable: root.activeStyleRow >= 0
    function gateOn(key) {
        const gates = root.activeStyleGates
        if (!gates || gates.showOverlay === undefined) return false
        return key === "overlay" ? gates.showOverlay === true : gates.showMedia === true
    }
    function toggleGate(key) {
        const row = root.activeStyleRow
        if (row < 0) return
        StyleListModel.setShowTemplate(row, key === "overlay" ? "overlay" : "media",
                                       !root.gateOn(key))
        root.gateRev++
    }
