        trimmed.isEmpty() ? QStringLiteral("Template Bus %1").arg(row + 1) : trimmed,
        QStringLiteral("template"), 75, false);
    {
        // The template's id rides BOTH plane nodes' meta, beside uiBusType: one
        // truth, restored with the rest of the graph on the next boot (pullRow
        // reads it back). Written after createBusRow — SetMeta needs the nodes.
